style.css:
@-moz-document domain("pinterest.com") {
/* ---- إعداد الخلفية واللون العام ---- */
  html, body {
    background-color: #000 !important;
    color: #FFFFFF !important;
  }

  /* متغير اللون اللي تريده (pastel pink) */
  :root {
    --my-pink: #FAE8ED;
  }

  /* ---- البوستات / البِنز (pins) ---- */
  [data-test-id="pin"],
  [data-test-id="pinWrapper"],
  article, .GrowthUnauthPin, .pinWrapper {
    background-color: #0f0f0f !important; /* بطانة خفيفة داخل البطاقة */
    border: 2px solid var(--my-pink) !important;
    border-radius: 12px !important;
    box-shadow: none !important;
  }

  /* ---- الخط داخل البوست (نص البوست) ----
     اخترت Poppins/Inter كخط افتراضي؛ لو تبي خط ثاني أقدر أعدله */
  [data-test-id="pin"] p,
  [data-test-id="pin"] span,
  [data-test-id="pin"] h1,
  [data-test-id="pin"] h2,
  [data-test-id="pin"] h3,
  .pinDescription, .pinMeta, .boardItemDescription {
    font-family: "Poppins", "Inter", Arial, sans-serif !important;
    color: #f4f4f6 !important;
    line-height: 1.35 !important;
  }

  /* ---- زر الحفظ (Save) ---- */
  button[aria-label*="Save"],
  button[aria-label*="حفظ"],
  .saveButton, .Button--save {
    background-color: #111 !important;
    color: #fff !important;
    border: 1px solid var(--my-pink) !important;
    border-radius: 8px !important;
    font-family: "Poppins", "Inter", Arial, sans-serif !important;
  }

  /* نص العنصر الحامل لكلمة Save (لو في span داخلي) */
  button[aria-label*="Save"] span,
  button[aria-label*="حفظ"] span {
    color: var(--my-pink) !important;
  }

  /* ---- شريط البحث ---- */
  input[type="search"], input[type="text"] {
    background-color: #111 !important;
    color: #fff !important;
    border: 1px solid var(--my-pink) !important;
    border-radius: 8px !important;
  }
  ::placeholder { color: #cfc9cc !important; }

  /* ---- عناصر الرأس والنافبار ---- */
  header, nav, [data-test-id="header"] {
    background-color: #000 !important;
    border-bottom: 1px solid rgba(250,232,237,0.12) !important;
  }

  /* ---- منع تغييرات مزعجة (تأكد انه ما يخفي عناصر) ---- */
  * {
    box-shadow: none !important;
    background-image: none !important;
  }

  /* ---- تحسين التباين للروابط وال Buttons ---- */
  a, button, span {
    color: #f5f5f5 !important;
  }
}
